contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, address target) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(!reverted || (c.owner() == beforeOwner && c.depositsCount() == beforeDeposits));
    }

    receive() external payable {}
}

